styles:
.spy-card {
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius);
      background: var(--is-bg-elev);
      padding: .85rem 1rem;
      margin: .5rem 0;
    }
    .spy-card h4 { margin: 0 0 .35rem; font-size: .9rem; }
    .spy-target-wrap {
      max-height: 18rem;
      overflow: auto;
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius);
      padding: .5rem .75rem;
    }
    .spy-target-wrap > * { margin: .5rem 0; }
    .spy-nav {
      display: flex; flex-direction: column; gap: .25rem;
    }
    .spy-nav a { padding: .25rem .5rem; border-radius: 6px; }
    .spy-nav a[aria-current="location"],
    .spy-nav a.is-scrollspy-active {
      background: color-mix(in srgb, var(--is-accent) 18%, transparent);
      color: var(--is-accent);
    }
